const removeUndefinedFieldsDeep = <T,>(value: T): T => {
	if (value === undefined) return value;
	if (value === null) return value;
	if (value instanceof Date) return value;

	if (Array.isArray(value)) {
		return value
			.map((item) => removeUndefinedFieldsDeep(item))
			.filter((item) => item !== undefined) as T;
	}

	if (typeof value === 'object') {
		const prototype = Object.getPrototypeOf(value);
		if (prototype && prototype !== Object.prototype) {
			return value;
		}

		const cleanedEntries = Object.entries(value as Record<string, unknown>)
			.filter(([, fieldValue]) => fieldValue !== undefined)
			.map(([key, fieldValue]) => [
				key,
				removeUndefinedFieldsDeep(fieldValue),
			])
			.filter(([, fieldValue]) => fieldValue !== undefined);

		return Object.fromEntries(cleanedEntries) as T;
	}

	return value;
};

const assertCanManagePropertyGroups = async (accountId: string) => {
	const accountOwnerDoc = await getDoc(doc(db, 'users', accountId));
	const accountOwnerData = accountOwnerDoc.data() || {};
	const subscription = accountOwnerData.subscription as SubscriptionData | undefined;

	if (!subscription || !canPropertyGroups(subscription)) {
		throw new Error(
			'Property groups are available on Property and Portfolio plans.',
		);
	}
};

const fetchPropertiesByIds = async (propertyIds: string[]): Promise<Property[]> => {
	if (propertyIds.length === 0) {
		return [];
	}

	const propertiesById = new Map<string, Property>();
	for (let i = 0; i < propertyIds.length; i += 10) {
		const batch = propertyIds.slice(i, i + 10);
		try {
			const propertiesQuery = query(
				collection(db, 'properties'),
				where('__name__', 'in', batch),
			);
			const propertiesSnapshot = await getDocs(propertiesQuery);
			const batchProperties = propertiesSnapshot.docs
				.map((propertyDoc) => docToData(propertyDoc) as Property)
				.filter(Boolean) as Property[];
			batchProperties.forEach((property) => {
				if (property?.id) {
					propertiesById.set(property.id, property);
				}
			});
		} catch (error) {
			console.warn('Could not fetch property batch by ids:', {
				batchSize: batch.length,
				error,
			});

			// Fallback to per-document reads so one unauthorized document does not
			// fail the entire batch and hide authorized properties.
			for (const propertyId of batch) {
				try {
					const propertyDoc = await getDoc(doc(db, 'properties', propertyId));
					const property = docToData(propertyDoc) as Property;
					if (property?.id) {
						propertiesById.set(property.id, property);
					}
				} catch (singleError) {
					console.warn('Could not fetch property by id fallback:', {
						propertyId,
						error: singleError,
					});
				}
			}
		}
	}

	return Array.from(propertiesById.values());
};

